changeSet.sql:
DROP POLICY IF EXISTS catalog_documents_owner_read ON nexus.catalog_documents;
CREATE POLICY catalog_documents_owner_read ON nexus.catalog_documents
    FOR SELECT TO CURRENT_USER USING (true);

DO $post$
DECLARE
    me            oid := (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname = current_user);
    pol_roles     oid[];
    exposed_roles text;
BEGIN
    SELECT pol.polroles INTO pol_roles
      FROM pg_catalog.pg_policy pol
     WHERE pol.polrelid = 'nexus.catalog_documents'::regclass AND pol.polname = 'catalog_documents_owner_read';
    IF pol_roles IS DISTINCT FROM ARRAY[me] THEN
        RAISE EXCEPTION 'owner-read policy catalog_documents_owner_read must name exactly the migrating role % and nothing else, found %', current_user, pol_roles;
    END IF;
    SELECT string_agg(r.rolname, ', ' ORDER BY r.rolname) INTO exposed_roles
      FROM pg_catalog.pg_roles r
     WHERE (r.rolname = 'nexus_svc' AND (r.rolname = current_user OR pg_catalog.pg_has_role(r.oid, current_user, 'USAGE')))
        OR (r.rolname <> current_user AND pg_catalog.pg_has_role(r.oid, current_user, 'USAGE')
            AND NOT r.rolsuper AND NOT r.rolbypassrls AND r.rolcanlogin);
    IF exposed_roles IS NOT NULL THEN
        RAISE EXCEPTION 'role(s) % have the privileges of the migrating role %; the owner-read policy would apply to them and let them read every tenant''s rows of nexus.catalog_documents', exposed_roles, current_user;
    END IF;
END
$post$;

